import { Router } from 'express';
import { z } from 'zod';
import type { DesignProfiles } from '../../services/profiles/DesignProfiles';
import type {
  TelemetryService,
  ProfileOperation,
} from '../../services/TelemetryService';
import {
  ReferenceDiscoveryRequestSchema,
  ReferenceProviderSchema,
} from '../../types/reference-connectors';
import {
  ReferencePlanRequestSchema,
  ReferenceApprovalSchema,
  ReferenceOnboardingActionSchema,
} from '../../types/reference-onboarding';
import type { ReferenceImportPlanSummary } from '../../types/api-responses';

export const createReferenceOnboardingRoutes = (
  profiles: DesignProfiles,
  telemetry?: TelemetryService,
) => {
  const router = Router();
  const operations: Record<string, ProfileOperation['operation']> = {
    'POST /profile/discoveries': 'reference_discovery',
    'POST /profile/import-plans': 'reference_plan',
    'POST /profile/import-plans/:id/imports': 'reference_approval',
    'PATCH /profile/onboarding': 'reference_onboarding',
  };
  router.use((req, res, next) => {
    const started = Date.now();
    res.once('finish', () => {
      const operation = operations[`${req.method} ${req.route?.path}`];
      if (operation)
        telemetry?.trackProfileOperation({
          stage: 'action',
          operation,
          outcome: res.statusCode < 400 ? 'completed' : 'failed',
          durationMs: Date.now() - started,
        });
    });
    next();
  });
  router.post('/profile/discoveries', async (req, res) => {
    const input = ReferenceDiscoveryRequestSchema.parse(req.body);
    const controller = new AbortController();
    res.once('close', () => {
      if (!res.writableEnded) controller.abort();
    });
    res.status(201).json(
      await profiles.discoverReferences({
        ...input,
        signal: controller.signal,
      }),
    );
  });
  router.post('/profile/import-plans', async (req, res) => {
    const input = ReferencePlanRequestSchema.parse(req.body);
    const controller = new AbortController();
    res.once('close', () => {
      if (!res.writableEnded) controller.abort();
    });
    res
      .status(201)
      .json(
        (await profiles.planReferences(
          input,
          controller.signal,
        )) satisfies ReferenceImportPlanSummary,
      );
  });
  router.get('/profile/import-plans/:id', async (req, res) => {
    res.json(
      await profiles.referencePlan(z.string().uuid().parse(req.params.id)),
    );
  });
  router.post('/profile/import-plans/:id/imports', async (req, res) => {
    const input = ReferenceApprovalSchema.parse({
      ...req.body,
      id: req.params.id,
    });
    res
      .status(202)
      .json(
        (await profiles.importReferences(
          input,
        )) satisfies ReferenceImportPlanSummary,
      );
  });
  router.get('/profile/onboarding', async (req, res) => {
    const { provider } = z
      .object({ provider: ReferenceProviderSchema.optional() })
      .strict()
      .parse(req.query);
    res.json(await profiles.referenceOnboarding(undefined, provider));
  });
  router.patch('/profile/onboarding', async (req, res) => {
    const { action, provider } = z
      .object({
        action: ReferenceOnboardingActionSchema,
        provider: ReferenceProviderSchema.optional(),
      })
      .strict()
      .parse(req.body);
    res.json(await profiles.referenceOnboarding(action, provider));
  });
  router.post('/profile/onboarding/notices', async (_req, res) => {
    const notice = await profiles.referenceNotice();
    if (notice)
      telemetry?.trackProfileOperation({
        stage: 'action',
        operation: 'reference_onboarding_offered',
        outcome: 'completed',
        durationMs: 0,
      });
    res.json({ notice });
  });
  return router;
};
